  async function loadBrowse(owner){if(!current(owner)||owner.busy)return;if(!owner.identity){owner.error='Entra en tu perfil personal para explorar tus rutinas.';drawBrowse(owner);return;}cancel(owner);const revision=owner.revision;owner.busy=true;owner.error='';drawBrowse(owner);try{const rows=catalog(await request(owner,CATALOG));if(!current(owner,revision))return;owner.catalog=rows;owner.loaded=true;if(owner.repeatSource){const reference=owner.repeatSource;const [content,history]=await Promise.all([request(owner,CATALOG+'/'+encodeURIComponent(reference.program_id)),request(owner,LOGS)]);if(!current(owner,revision))return;const program=detail(content,reference.program_id),saved=logsSnapshot(history),record=saved.logs.find(row=>row.session_id===reference.session_id);if(saved.version!==reference.logs_version||program.content_version!==reference.content_version||!record||!rows.some(row=>row.id===program.id&&row.content_version===program.content_version))throw new Error('El registro anterior cambió o dejó de estar disponible. Vuelve a elegirlo desde Progreso.');targetsFromLog(program,record);owner.program=program;owner.repeatLog=record;owner.targets=makeTargetsDraft(program);owner.targetsEnabled=false;owner.startDate=today(owner.timezone);owner.checked={equipment:[],capabilities:[]};}}catch(error){if(current(owner,revision)&&error.name!=='AbortError'){owner.repeatSource=null;owner.repeatLog=null;owner.targets=null;owner.targetsEnabled=false;fail(owner,error);}}finally{if(current(owner,revision)){owner.busy=false;drawBrowse(owner);}}}
